import {WORKS,pickQuestions} from './bank.js';
export const QUESTIONS=WORKS.math.questions;
export const EVENT_NAMES = {
  native_start:'Контроль Windows включён',native_stop:'Контроль Windows остановлен',native_process:'Обнаружена программа из списка',native_monitors:'Несколько дисплеев',native_display_change:'Изменились дисплеи',native_foreground:'Другое приложение активно',native_overlay:'Окно поверх других',native_clipboard:'Изменение системного буфера',native_removable:'Съёмный диск',native_sensor_error:'Датчик Windows недоступен',native_lost:'Связь с Windows потеряна',face_missing:'Лицо отсутствует',multiple_faces:'Несколько лиц',camera_frozen:'Камера не обновляется',face_error:'Модель лица недоступна',recording_error:'Ошибка локальной записи',

  dom_tamper:'Изменена страница вопросов',script_added:'Обнаружен новый SCRIPT-элемент',synthetic_input:'Программное событие ответа',csp_violation:'Политика браузера заблокировала действие',sensor_test:'Контрольная проверка датчика',probe_start:'Проба скрипта начата',probe_end:'Проба скрипта завершена',
  pause:'Вопросы скрыты', resume:'Сеанс возобновлён', extension_new_tab:'Новая вкладка', extension_tab_switch:'Переключение вкладки', extension_window_blur:'Другое окно браузера', extension_navigation:'Навигация экзамена', extension_lost:'Связь с расширением потеряна', start:'Сеанс начат', finish:'Сеанс завершён', blur:'Окно потеряло фокус', focus:'Фокус возвращён', hidden:'Вкладка скрыта', visible:'Вкладка снова видна',
  fullscreen_exit:'Выход из полного экрана', fullscreen_enter:'Полный экран включён', copy:'Попытка копирования', cut:'Попытка вырезания', paste:'Попытка вставки', contextmenu:'Контекстное меню',
  shortcut:'Получено сочетание клавиш', camera_ended:'Камера отключена', mic_ended:'Микрофон отключён', screen_ended:'Демонстрация экрана остановлена', loud_audio:'Продолжительный громкий звук', media_error:'Ошибка источника'
};
export function formatTime(seconds) { const n=Math.max(0,Math.ceil(seconds)); return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`; }
export function grade(questions, answers) {return questions.map(q=>({id:q.id, selected:answers[q.id]??null, correct:q.correct, ok:answers[q.id]===q.correct}));}
export function shortcutLabel(event) { const parts=[]; if(event.ctrlKey)parts.push('Ctrl');if(event.altKey)parts.push('Alt');if(event.shiftKey)parts.push('Shift');if(event.metaKey)parts.push('Meta');parts.push(event.code||event.key);return parts.join('+');}
export function isMonitoredShortcut(event) {return !!(event.ctrlKey||event.metaKey||event.altKey)&&!['ControlLeft','ControlRight','AltLeft','AltRight','ShiftLeft','ShiftRight','MetaLeft','MetaRight'].includes(event.code);}
export class Session {
  constructor(clock=()=>Date.now()){this.clock=clock;this.state='idle';this.events=[];this.sequence=0;this.probes=[];this.answers={};this.started=null;this.ended=null;this.questions=[];this.config={};this.paused=null;}
  start({count=3,duration=300,fullscreen=true,clipboard=true,strict=false,integrity=true,work='math',variant=0}={}){
    if(this.state==='active')throw new Error('Сеанс уже активен');
    if(![1,2,3].includes(Number(count))||!Number.isFinite(Number(duration))||Number(duration)<=0)throw new Error('Некорректные настройки');
    if(!WORKS[work])throw new Error('Неизвестная работа');
    this.paused=null;this.state='active';this.events=[];this.sequence=0;this.probes=[];this.answers={};this.started=this.clock();this.ended=null;this.questions=pickQuestions(work,Number(count),Number(variant)||0);this.config={count:Number(count),duration:Number(duration),fullscreen:!!fullscreen,clipboard:!!clipboard,strict:!!strict,integrity:!!integrity,work,variant:Number(variant)||0};this.record('start','info');return this;
  }
  record(type,level='warning',detail=''){if(this.state!=='active')return false;this.events.push({seq:++this.sequence,at:new Date(this.clock()).toISOString(),elapsedMs:this.clock()-this.started,type,label:EVENT_NAMES[type]||type,level,detail:String(detail).slice(0,160)});if(this.events.length>2000)this.events.shift();if(this.config.strict&&level==='warning'&&!this.paused&&['native_process','native_monitors','native_display_change','native_foreground','native_overlay','native_clipboard','native_removable','native_sensor_error','native_lost','face_missing','multiple_faces','camera_frozen','face_error','recording_error','loud_audio','dom_tamper','script_added','synthetic_input','csp_violation','blur','hidden','fullscreen_exit','copy','cut','paste','contextmenu','camera_ended','mic_ended','screen_ended','extension_new_tab','extension_tab_switch','extension_window_blur','extension_navigation','extension_lost'].includes(type)){this.paused=type;this.record('pause','info',EVENT_NAMES[type]||type);}return true;}
  resume(){if(this.state!=='active'||!this.paused)return false;this.paused=null;this.record('resume','info');return true;}
  choose(id,option){if(this.state!=='active'||this.paused||!this.questions.some(q=>q.id===id)||!['1','2','3','4'].includes(option))return false;this.answers[id]=option;return true;}
  remaining(){if(this.started===null)return this.config.duration||300;return Math.max(0,this.config.duration-((this.ended??this.clock())-this.started)/1000);}
  finish(reason='manual'){if(this.state!=='active')return false;this.record('finish','info',reason);this.ended=this.clock();this.state='finished';return this.report();}
  report(){const results=grade(this.questions,this.answers);return {schemaVersion:3,paused:this.paused,kind:'browser-training-simulator',state:this.state,startedAt:this.started===null?null:new Date(this.started).toISOString(),endedAt:this.ended===null?null:new Date(this.ended).toISOString(),config:{...this.config},score:results.filter(x=>x.ok).length,total:results.length,results,warnings:this.events.filter(e=>e.level==='warning').length,events:this.events.map(e=>({...e})),probes:JSON.parse(JSON.stringify(this.probes)),limitations:'Page evidence only; native evidence is attached separately when connected. No events does not prove undetectability. No universal OS screenshot detector or remote attestation. Optional recordings remain on this device.'};}
}
